import { CustomTooltip } from 'components/CustomTooltip';
import { ChevronDown } from 'components/icon';
import { StyledTooltip } from 'shared/Styles';

import { DDT_COLORS, DDT_SPACING } from '../../DrillDownTable.styles';
import {
  DrillDownCell,
  DrillDownColumnGroup,
  DrillDownRow,
} from '../../DrillDownTable.types';
import {
  DDTAxisCell,
  DDTCell,
  DDTChevronButton,
  DDTChevronSpacer,
  DDTChevronWrapper,
  DDTDataGroup,
  DDTDataGroupsWrapper,
  DDTDriverContent,
  DDTDriverLabel,
  DDTRow,
  DDTSquareBrandImg,
} from './DrillDownTableRow.styles';

const ROW_BG = [
  DDT_COLORS.background.white, // level 0 (even)
  DDT_COLORS.background.level1,
  DDT_COLORS.background.level2,
  DDT_COLORS.background.level3,
  DDT_COLORS.background.level4,
];

const ROW_BG_LEVEL0_ODD = '#F5FAFF';

function resolveRowBg(level: number, isEven: boolean): string {
  const clampedLevel = Math.max(level, 0);
  if (clampedLevel === 0) {
    return isEven ? ROW_BG[0] : ROW_BG_LEVEL0_ODD;
  }
  if (clampedLevel >= ROW_BG.length) {
    return DDT_COLORS.background.levelDeep;
  }
  return ROW_BG[clampedLevel];
}

function resolveCellColor(cell: DrillDownCell | undefined): string {
  if (cell?.value == null) return DDT_COLORS.text.secondary;
  switch (cell.type) {
    case 'positive':
      return DDT_COLORS.text.positive;
    case 'negative':
      return DDT_COLORS.text.negative;
    case 'neutral':
      return DDT_COLORS.text.neutral;
    default:
      return DDT_COLORS.text.primary;
  }
}

function resolveCellDisplay(cell: DrillDownCell | undefined): string {
  if (cell?.value == null) return '-';
  return String(cell.value);
}

export interface DrillDownTableRowProps {
  readonly row: DrillDownRow;
  readonly rowIdx: number;
  readonly columnGroups: DrillDownColumnGroup[];
  readonly axisWidth: string;
  readonly expandedIds: Set<string>;
  readonly onToggleRow: (id: string) => void;
  readonly dataTestId?: string;
}

export const DrillDownTableRow: React.FC<DrillDownTableRowProps> = ({
  row,
  rowIdx,
  columnGroups,
  axisWidth,
  expandedIds,
  onToggleRow,
  dataTestId,
}) => {
  const testId = (suffix: string) =>
    dataTestId ? `${dataTestId}-${suffix}` : undefined;

  const isExpanded = expandedIds.has(row.id);
  const indent = row.level * DDT_SPACING.indentStep;
  const axisWidthStyle = {
    '--ddt-axis-width': axisWidth,
  } as React.CSSProperties;
  const label = <DDTDriverLabel>{row.label}</DDTDriverLabel>;

  return (
    <DDTRow
      style={
        {
          '--ddt-row-bg': resolveRowBg(row.level, rowIdx % 2 === 0),
        } as React.CSSProperties
      }
      role="row"
      aria-expanded={row.hasChildren ? isExpanded : undefined}
      data-testid={testId(`row-${row.id}`)}
    >
      <DDTAxisCell
        style={axisWidthStyle}
        role="rowheader"
        data-testid={testId(`cell-axis-${row.id}`)}
      >
        <DDTDriverContent
          style={{ '--ddt-indent': `${indent}px` } as React.CSSProperties}
        >
          {row.hasChildren ? (
            <DDTChevronButton
              type="button"
              onClick={() => onToggleRow(row.id)}
              aria-label={isExpanded ? 'Collapse row' : 'Expand row'}
              aria-expanded={isExpanded}
              aria-controls={testId(`row-${row.id}`)}
              data-testid={testId(`chevron-${row.id}`)}
            >
              <DDTChevronWrapper $expanded={isExpanded}>
                <ChevronDown size="tiny" />
              </DDTChevronWrapper>
            </DDTChevronButton>
          ) : (
            <DDTChevronSpacer aria-hidden="true" />
          )}

          {row.logoSrc && (
            <DDTSquareBrandImg src={row.logoSrc} alt={row.label} />
          )}

          {row.tooltipContent ? (
            <CustomTooltip
              content={
                <StyledTooltip size="small">{row.tooltipContent}</StyledTooltip>
              }
            >
              {label}
            </CustomTooltip>
          ) : (
            label
          )}
        </DDTDriverContent>
      </DDTAxisCell>

      <DDTDataGroupsWrapper>
        {columnGroups.map((group, gIdx) => {
          const isLastGroup = gIdx === columnGroups.length - 1;
          return (
            <DDTDataGroup key={group.id} $isLast={isLastGroup}>
              {group.columns.map((col, cIdx) => {
                const isLastCol = cIdx === group.columns.length - 1;
                const cell = row.cells[col.id];
                return (
                  <DDTCell
                    key={col.id}
                    role="cell"
                    $isLast={isLastCol}
                    style={{
                      flex: col.width ? `0 0 ${col.width}` : 1,
                      width: col.width || 'auto',
                      color: resolveCellColor(cell),
                    }}
                    data-testid={testId(`cell-${row.id}-${col.id}`)}
                  >
                    {cell?.tooltip ? (
                      <CustomTooltip
                        content={
                          <StyledTooltip size="small">
                            {cell.tooltip}
                          </StyledTooltip>
                        }
                      >
                        <span>{resolveCellDisplay(cell)}</span>
                      </CustomTooltip>
                    ) : (
                      resolveCellDisplay(cell)
                    )}
                  </DDTCell>
                );
              })}
            </DDTDataGroup>
          );
        })}
      </DDTDataGroupsWrapper>
    </DDTRow>
  );
};
